---Execute
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuideActionNode:Execute(moduleStepVo)
    local actionInfoStr = moduleStepVo.actionInfo
    if string.isEmpty(actionInfoStr) then 
        --- 直接从 RootCanvas 向下取 所有 Animator
        local dialog = UIModule.CurrentScreen:LastDialog()
        if not isNull(dialog) then
            local transform = dialog.transform
            GuideUtils.CheckChildAnimatesByTransform(transform)
            
        end
        return 
    end
    self:ParseActionInfo(actionInfoStr, moduleStepVo.renderCameraType)

    local context = self.context
    local actionNodeList = context:GetActionNodeList()
    if actionNodeList == nil then
        return
    end
    local actionBehavior = moduleStepVo.actionBehavior
    if string.isEmpty(actionBehavior) then return end
    self:ParseActionBehavior(actionBehavior, moduleStepVo.actionHLParams)
end


