function UISystemGuideActionNode:ParseActionInfo(actionInfoStr, renderCameraType)
    -- ---@type UnityEngine.Camera
    -- local cam = UIModule.RootCanvas.defaultCamera
    -- local orthographic = cam.orthographic
    -- local isChange = orthographic == false
    -- if isChange then
    --     cam.orthographic = true
    -- end
    self.renderCameraType = renderCameraType
    local actionInfoList = ParseStringByLevel(SplitFlagLevel.Level1, actionInfoStr)
    for i, actionNodeParamsStr in ipairs(actionInfoList) do
        local actionNodeType, actionParams, nodeType = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, actionNodeParamsStr))
        if renderCameraType >= GuideNodeCameraType.UICamera then
            nodeType = checkNumber(nodeType)
        else
            nodeType = 0
        end
        self:InitActionNodeList(actionNodeType, actionParams, nodeType, i)

    end
    
    self:FocusNodes()

    -- if isChange then
    --     cam.orthographic = orthographic
    --     Events.Broadcast(Constants.EventNames.EVENT_GUIDE_RECOVER_UI_CAMERA)
    -- end
end

function UISystemGuideActionNode:FocusNodes(immediately, isReload)
    local context        = self.context
    local actionNodeList = context:GetActionNodeList()
    if actionNodeList == nil then
        return
    end
    local isSpecifyEventNode = context:GetIsSpecifyEventNode() or context:GetEventNodeIs3D()
    if isSpecifyEventNode or isReload then
        context:ClearMaskCache()
    end

    local renderCameraType = self.renderCameraType
    local actionNodeCount = #actionNodeList
    local camera = GuideUtils.GetGuideNodeRenderCameraByType(renderCameraType)
    

    -- for i = 1, actionNodeCount, 1 do
    --     context:CheckHighlightRegionEffectIsComplete(i)
    -- end
    if actionNodeCount == 1 then
        local rt = actionNodeList[1].transform
        GuideUtils.CheckPivot(rt, function()
            -- if isSpecifyEventNode then
                -- context:AddCornersByRectTransform(rt)
            -- end
            
            context:FocusOn(rt, checkBool(immediately), camera)
            
            if renderCameraType >= GuideNodeCameraType.MainCamera then
                context:Fresh3DUIHighlightRegion(1)
            elseif isReload then
                --- 重载缩放不变
                local localScale = nil
                context:ShowHighlightRegion(rt, 1, localScale, renderCameraType, isReload)
            end
        end)

    elseif actionNodeCount > 1 then
        GuideUtils.CheckPivotByNodes(actionNodeList, function()
            -- if isSpecifyEventNode then
            --     for i, v in ipairs(actionNodeList) do
            --         context:AddCornersByRectTransform(v.transform)
            --     end
            -- end
            local list = {}
            for i, rect in ipairs(actionNodeList) do
                table.insert(list, rect)
            end
            for i = #list, 4, 1 do
                local lastItem = list[#list]
                table.insert(list, lastItem)
            end
            context:FocusOnPlural(actionNodeList, camera)
            
            for index = 1, actionNodeCount, 1 do
                if renderCameraType >= GuideNodeCameraType.MainCamera then
                    context:Fresh3DUIHighlightRegion(index)
                elseif isReload then
                    --- 重载缩放不变
                    local localScale = nil
                    local actionNode = actionNodeList[index]
                    context:ShowHighlightRegion(actionNode, index, localScale, renderCameraType, isReload)
                end
            end
        end)

    end
   
end

function UISystemGuideActionNode:InitActionNodeList(actionNodeType, actionParams, nodeType, index)
    actionNodeType = checkNumber(actionNodeType)
    if actionNodeType == ActionType.UI then
        self:HandleTypeUI(actionParams, nodeType, index)

    elseif actionNodeType == ActionType.UICustomRegion then
        self:HandleTypeUICustomRegion(actionParams, nodeType, index)

    elseif actionNodeType == ActionType.UIList then
        self:HandleTypeUIList(actionParams, nodeType, index)

    elseif actionNodeType == ActionType.UIListCustomRegion then
        self:HandleTypeUIListCustomRegion(actionParams, nodeType, index)

    elseif actionNodeType == ActionType.ThreeDimensionalObject then
        self:HandleTypeThreeDimensionalObject(actionParams, index)

    end
end

function UISystemGuideActionNode:HandleTypeUI(actionParams, nodeType, index)
    local params = ParseStringByLevel(SplitFlagLevel.Level3, actionParams)
    local nodePath, scaleX, scaleY = SafeUnpack(params)
    local node = GuideUtils.GetNode(nodePath, nodeType)

    ---节点为空不处理
    if isNull(node) then return end

    scaleX = checkNumber(scaleX) > 0 and checkNumber(scaleX) or 1
    scaleY = checkNumber(scaleY) > 0 and checkNumber(scaleY) or 1
    GuideUtils.CheckParentAnimatesByTransform(node.transform)
    GuideUtils.CheckPivot(node, function()
        self.context:ShowHighlightNode(node, index, Vector3.New(scaleX, scaleY, 1), self.renderCameraType)
    end)
end

function UISystemGuideActionNode:HandleTypeUICustomRegion(actionParams, nodeType, index)
    local params = ParseStringByLevel(SplitFlagLevel.Level3, actionParams)
    local parentPath   = params[1]
    local parent       = GuideUtils.GetNode(parentPath, nodeType)
    ---节点为空不处理
    if isNull(parent) then return end
    GuideUtils.CheckParentAnimatesByTransform(parent.transform)
    self.context:ShowCustomRegionNode(parent, params, 2, index, self.renderCameraType)

end

function UISystemGuideActionNode:HandleTypeUIList(actionParams, nodeType, index)
    --3,UICultivateEquipMainDialog/Container/EquipBackpackNode/ScrollRoot/ScrollView:0:GoodNode/Container
    ---@type UISystemGuideDialog
    local context = self.context
    local params = ParseStringByLevel(SplitFlagLevel.Level3, actionParams)
    local nodePath, nodeIndex, path, isMove, scaleX, scaleY, subCellIndex = SafeUnpack(params)
    
    local node = GuideUtils.GetListCell(nodePath, nodeIndex, path, checkNumber(isMove) == 1, subCellIndex, nodeType)
    if not isNull(node) then
        GuideUtils.CheckParentAnimatesByTransform(node.transform)
        local rt = KTool.GetComponent(node.gameObject, RectTransformType)
        scaleX = checkNumber(scaleX) > 0 and checkNumber(scaleX) or 1
        scaleY = checkNumber(scaleY) > 0 and checkNumber(scaleY) or 1
        GuideUtils.CheckPivot(rt, function()
            context:ShowHighlightNode(rt, index, Vector3.New(scaleX, scaleY, 1), self.renderCameraType)
        end)
    end

end

function UISystemGuideActionNode:HandleTypeUIListCustomRegion(actionParams, nodeType, index)
    --4,UICultivateEquipMainDialog/Container/EquipBackpackNode/ScrollRoot/ScrollView:0:GoodNode:0:0:231:231:0.5:0.5:0.5:0.5:0.9:0.9
    local context  = self.context
    local params = ParseStringByLevel(SplitFlagLevel.Level3, actionParams)
    local nodePath, nodeIndex, path, isMove = params[1], params[2], params[3], params[4]
    local parent   = GuideUtils.GetListCell(nodePath, nodeIndex, path, checkNumber(isMove) == 1, nodeType)
    --- 检查是否为空
    if isNull(parent) then return end
    
    GuideUtils.CheckParentAnimatesByTransform(parent.transform)
    context:ShowCustomRegionNode(parent, params, 5, index, self.renderCameraType)
end

function UISystemGuideActionNode:HandleTypeThreeDimensionalObject(actionParams, index)
    local context = self.context
    local params = ParseStringByLevel(SplitFlagLevel.Level3, actionParams)
    local node    = context.CustomRegion
    GuideUtils.CheckParentAnimatesByTransform(node.transform)
    context:ShowRegionNode(node, params, 1, index, self.renderCameraType)
    --local vecNow = CfUtils.WorldPosition2UIPosition(self.eventNode.transform.position, self.ActionElementContainer)
    --node.anchoredPosition = vecNow
    --self.ThreeDimensionalObjectPosition = nil
end

