function UISystemGuideActionNode:ParseActionBehavior(actionBehaviorStr, actionHLParams)
    local actionBehaviorList = ParseStringByLevel(SplitFlagLevel.Level1, actionBehaviorStr)
    local actionHLParamList = ParseStringByLevel(SplitFlagLevel.Level1, actionHLParams)
    --local actionBehaviorList = parse_strings(actionBehaviorStr, ";")
    --local actionHLParamList = parse_strings(actionHLParams, ";")
    for i, actionBehaviorParamsStr in ipairs(actionBehaviorList) do
        local actionBehaviorParamsList = ParseStringByLevel(SplitFlagLevel.Level2, actionBehaviorParamsStr)
        --local actionBehaviorParamsList = parse_strings(actionBehaviorParamsStr, "||")
        for index, oneActionBehaviorParams in ipairs(actionBehaviorParamsList) do
            self:OpenActionNodeBehavior(oneActionBehaviorParams, i, actionHLParamList[i])
        end

    end
end

function UISystemGuideActionNode:OpenActionNodeBehavior(oneActionBehaviorParams, index, actionHLParam)
    local actionBehaviorType, actionBehaviorParams, offsetX, offsetY = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level3, oneActionBehaviorParams))
    --local actionBehaviorType, actionBehaviorParams, offsetX, offsetY = SafeUnpack(parse_strings(oneActionBehaviorParams, "#"))
    actionBehaviorType = checkNumber(actionBehaviorType)
    if actionBehaviorType == ActionNodeBehaviorType.ShowFinger then
        self:UpdateFingerShowState(index, true)

    elseif actionBehaviorType == ActionNodeBehaviorType.ShowArrow then
        self:UpdateArrowNodeShowState(index, true, checkNumber(actionBehaviorParams), offsetX, offsetY)

    elseif actionBehaviorType == ActionNodeBehaviorType.ShowHighlightFrame then
        self:UpdateHighlightFrameShowState(index, true, actionHLParam)

    end
end

---UpdateFingerShowState
---更新手指显示状态
---@param isShow boolean
function UISystemGuideActionNode:UpdateFingerShowState(index, isShow)
    --KTool.SetActive(self.StepIconClick, isShow)
    local context        = self.context
    local actionNodeList = context:GetActionNodeList()
    
    local node           = actionNodeList[index]
    if isNull(node) then
        return
    end

    local highlightRegion = context:GetHighlightRegionNodeByIndex(index)
    ---@type UISystemHighlightRegionNode
    local env = CfUtils.GetLuaScr(highlightRegion, HighlightRegionNodeEnvPath)
    if not isNull(env) then
        env:UpdateFingerShowState(isShow, node.transform)
    end
end

---UpdateArrowNodeShowState
---更新箭头显示状态
