function UISystemGuideActionNode:Reload(immediately, moduleStepVo)
    if immediately == nil then
        immediately = true
    end

    self:FocusNodes(immediately, true)

    local actionBehavior = moduleStepVo.actionBehavior
    if string.isEmpty(actionBehavior) then return end
    self:ParseActionBehavior(actionBehavior, moduleStepVo.actionHLParams)
end

